  if(!entry||(auditReaction(entry).decision!=='KEEP'&&!(entry.industrialEducation&&analyze(entry.reaction).valid&&analyze(entry.reaction).metrics.atom.value!==null))){toast('This option is no longer applicable. Review the current recommendations.');return;}
  state.overrides={...clone(entry.reaction),_recommendation:{id:option.id,title:entry.label,evidence:option.efficiency,edited:false}};state.baseline=null;
  if(state.tab==='Dashboard'&&state.guide.active){state.guide.ready=true;state.guide.step=4;}else state.tab='Compare';
  persist();render();const transitionPanel=document.querySelector('.transformation');if(transitionPanel&&motionAllowed()){const status=document.createElement('p');status.className='apply-status';status.setAttribute('role','status');status.textContent='Applying greener changes…';transitionPanel.prepend(status);setTimeout(()=>{if(status.isConnected)status.textContent='✓ Scenario applied · results recalculated';},800);}if(state.tab==='Dashboard')guideFocus();else window.scrollTo?.({top:0,behavior:'instant'});toast('Educational optimization applied. Original inputs are preserved; comparison shows calculated changes.');return;
