function reactionEducation(r,opportunityOnly=false){
 const p=exhibitionProfiles[r.libraryId];if(!p)return '';
 const entry=reactionLibrary.find(e=>e.id===r.libraryId);
 const links=[p.source||entry?.source,p.greenSource,entry?.optimization?.source,p.applicationSource].filter((v,i,a)=>v&&a.indexOf(v)===i);
 return `<details class="${opportunityOnly?'card':''}"><summary>${opportunityOnly?'Green Chemistry Opportunities':'Reaction Overview & real-world context'}</summary><p class="small muted">Reference context for the loaded demo. Edited inputs are not chemically verified; these descriptions do not predict their outcome.</p>${opportunityOnly?'':`<h3>Reaction Overview</h3><p>${esc(p.overview)}</p><h3>Real-World Applications</h3><p><b>Industry:</b> ${esc(p.industry)}<br><b>Application:</b> ${esc(p.application)}<br><b>Importance:</b> ${esc(p.importance)}</p><h3>Environmental Considerations</h3><p>${esc(p.environment)}</p>`}<h3>Green Chemistry Opportunities</h3><p>${esc(p.opportunities)}</p>${p.conditions?`<p><b>Operating context:</b> ${esc(p.conditions)}</p><p><b>Catalyst:</b> ${esc(r.catalystIdentity||'No catalyst used in this reaction.')}</p><p>Educational Assumptions: initial quantities and yield illustrate arithmetic only. No plant performance or numerical optimization is predicted. Explore supported research directions or supply your own documented what-if inputs in Optimize.</p>`:''}<p class="small">${links.map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Reference ${i+1} ↗</a>`).join(' · ')}</p></details>`;
}
function engineeringScope(){return `<details class="card"><summary>Scope of Green Chemistry in Engineering</summary><p><b>Chemical manufacturing:</b> Reduce waste and improve material efficiency; explore ammonia and methanol.</p><p><b>Mechanical & materials engineering:</b> Cleaner material production and recovery; explore iron, PLA and PET.</p><p><b>Energy engineering:</b> Study hydrogen routes and their dependence on energy supply.</p><p><b>Pharmaceutical manufacturing:</b> Reduce hazardous substances and waste in synthesis.</p><p><b>Environmental engineering:</b> Prevent pollution and improve resource efficiency.</p><p><b>Sustainable industrial development:</b> Assess safer, cleaner technologies across their full process boundaries.</p>${button('Explore reaction examples','demos','text-button')}</details>`;}
function comparisonInsights(left,right,l,r){
 const notes=[];
 if(!sameTarget(l,r))notes.push('The target products differ. Direct improvements cannot be inferred from these metrics.');
 else {
  for(const m of metricChanges(l,r)){if(m.before===null||m.after===null)notes.push(`${m.title}: Data unavailable for a comparable pair.`);else if(m.before!==m.after)notes.push(`${m.title}: ${format(m.before)} → ${format(m.after)} ${m.unit}. ${m.status}.`);}
  if(l.wasteMass!==null&&r.wasteMass!==null&&l.wasteMass!==r.wasteMass)notes.push(`Waste in the supplied boundary: ${format(l.wasteMass)} → ${format(r.wasteMass)} g. This is not an emissions inventory.`);
  if(l.score!==null&&r.score!==null&&sameCoverage(l,r))notes.push(`Educational Green Score: ${format(l.score)} → ${format(r.score)}. Calculated from the same available categories, not a lifecycle result.`);
  else notes.push('Green Score comparison needs matching target and category coverage.');
 }
 if(left.solvent!==right.solvent||left.solventMass!==right.solventMass)notes.push(`Solvent input: ${left.solvent} (${left.solventMass===''?'Data unavailable':left.solventMass+' g'}) → ${right.solvent} (${right.solventMass===''?'Data unavailable':right.solventMass+' g'}). Reference rankings do not verify compatibility.`);
 if(left.catalyst!==right.catalyst||left.catalystMass!==right.catalystMass)notes.push('Catalyst inputs changed. The app does not calculate catalyst sustainability, activity or selectivity.');
 if(l.energyIndex!==null&&r.energyIndex!==null&&l.energyIndex!==r.energyIndex)notes.push(`Temperature/time proxy: ${format(l.energyIndex)} → ${format(r.energyIndex)} °C·h. This is not measured energy consumption.`);
 notes.push('Measured energy consumption, emissions and quantitative catalyst sustainability: Data unavailable. Missing data does not establish an improvement.');
 return `<details class="card"><summary>Key Comparison Insights</summary><ul>${notes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="small">Differences describe supplied inputs within their stated boundaries. Educational scenarios are assumptions, not experimentally demonstrated gains.</p></details>`;
}

function simulationPage(){
 if(!analyze(state.reaction).exists)return empty('Choose a reaction to simulate.','Load a demo or enter a reaction in Reaction Analysis.');
 simulation??=newSimulation(state.reaction);const a=analyze(simulation.draft),changed=JSON.stringify(state.reaction)!==JSON.stringify(simulation.original);
 return `<div class="lgg-simulation">${title('WHAT-IF WORKSPACE','Reaction Simulator','Separate temporary assumptions, recalculated by the existing engine.',button('Load Demo Reaction','demos')+button('Use current reaction','simulation-use-current'))}<p class="note">Original snapshot: <b>${esc(simulation.original.name)}</b>. Simulation resets to this snapshot. ${changed?'The current reaction has changed; choose Use current reaction to start from it.':''} Simulation inputs are temporary and are not saved by Save reaction.</p><div class="dashboard-grid">${simulationControls(simulation)}<div>${scorecard(a,'simulation')}${simulationDifferences(simulation)}</div></div>${metrics(a,false,simulation.draft)}</div>`;
}
